import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import './EventsSlider.css'; // Özel CSS dosyanız
import React from "react";
import Slider from "react-slick";

const SliderComponent = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
  };

  return (
    <div
      style={{
        position: "relative",
        width: "1409px",
        height: "737px",
        background: "#FFFFFF",
      }}
    >
      <div
        style={{
          display: "flex",
          flexDirection: "column",
          alignItems: "flex-start",
          padding: "0px",
          gap: "4px",
          position: "absolute",
          width: "1024px",
          height: "394.42px",
          left: "208px",
          top: "136px",
        }}
      >
        <div
          style={{
            display: "flex",
            flexDirection: "row",
            justifyContent: "space-between",
            alignItems: "flex-start",
            padding: "0px",
            gap: "851px",
            width: "1024px",
            height: "17.42px",
          }}
        >
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              padding: "0px",
              gap: "10px",
              width: "30.16px",
              height: "11.11px",
              background: "#293349",
            }}
          />
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              alignItems: "flex-start",
              padding: "0px",
              gap: "10px",
              width: "143px",
              height: "17.42px",
              background: "#293349",
            }}
          />
        </div>

        <Slider {...settings}>
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "center",
              alignItems: "flex-start",
              padding: "0px",
              gap: "4px",
              width: "1024px",
              height: "373px",
            }}
          >
            <div
              style={{
                width: "987.46px",
                height: "373px",
                background: "#293349",
                borderWidth: "0px 15px 15px 0px",
                borderStyle: "solid",
                borderColor: "#00C26D",
              }}
            />
          </div>
          <div
            style={{
              display: "flex",
              flexDirection: "row",
              justifyContent: "center",
              alignItems: "center",
              padding: "20px 0px",
              gap: "20px",
              width: "1024px",
              height: "373px",
              background: "#00C26D",
            }}
          >
            <h3 style={{ color: "#fff" }}>Slide 2</h3>
          </div>
        </Slider>
      </div>

      <div
        style={{
          position: "absolute",
          width: "1409px",
          height: "178px",
          left: "0px",
          top: "559px",
          background: "#293349",
        }}
      />
    </div>
  );
};

export default SliderComponent;
